int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    ll B;
    cin >> n >> B;
    vector<vector<int>> ch(n);
    vector<int> k(n);
    vector<ll> a(n), d(n), b(n);
    for (int i = 0, p; i < n; i++) {
        cin >> p >> k[i] >> a[i];
        if (p)
            ch[p - 1].push_back(i);
    }
    const ll INF = 4e18;
    for (int u = n - 1; u >= 0; u--) {
        if (ch[u].empty()) {
            d[u] = a[u];
            b[u] = max(0LL, a[u] - B);
            continue;
        }
        auto v = ch[u];
        sort(v.begin(), v.end(), [&](int x, int y) { return d[x] < d[y]; });
        int z = k[u] - 1;
        d[u] = d[v[z]] + a[u];
        b[u] = INF;
        for (int j = 0; j < (int)v.size(); j++) {
            ll lo = z ? d[v[z - 1 + (j < z)]] : 0;
            int h = z + (j <= z);
            ll hi = h < (int)v.size() ? d[v[h]] : INF;
            b[u] = min(b[u], min(hi, max(lo, b[v[j]])) + a[u]);
        }
    }
    cout << b[0] << '\n';
}

