t = sys.stdin.buffer.read().split()
ha, wa, hb, wb = map(int, t[:4])
A = {(r, c) for r in range(ha) for c in range(wa) if t[4 + r][c] == 49}
B = {(r, c) for r in range(hb) for c in range(wb) if t[4 + ha + r][c] == 49}
dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))


def components(s, stop=10**9):
    s = set(s)
    count = 0
    while s:
        count += 1
        if count > stop:
            return count
        stack = [s.pop()]
        while stack:
            r, c = stack.pop()
            for dr, dc in dirs:
                z = (r + dr, c + dc)
                if z in s:
                    s.remove(z)
                    stack.append(z)
    return count


best = 10**9
ways = 0
if A and B:
    for dx in range(1 - hb, ha):
        for dy in range(1 - wb, wa):
            V = {(r + dx, c + dy) for r, c in B}
            I = A & V
            if not I or components(I, 1) != 1:
                continue
            U = A | V
            if components(U, 1) != 1:
                continue
            x0 = min(0, dx) - 1
            x1 = max(ha, dx + hb)
            y0 = min(0, dy) - 1
            y1 = max(wa, dy + wb)
            W = {(r, c) for r in range(x0, x1 + 1) for c in range(y0, y1 + 1)} - U
            if components(W, 2) != 2:
                continue
            per = sum((r + dr, c + dc) not in U for r, c in U for dr, dc in dirs)
            if per < best:
                best = per
                ways = 1
            elif per == best:
                ways += 1
print(best if ways else -1, ways)

