#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int ha, wa, hb, wb;
    cin >> ha >> wa >> hb >> wb;
    vector<pair<int, int>> A, B;
    string s;
    for (int r = 0; r < ha; r++) {
        cin >> s;
        for (int c = 0; c < wa; c++)
            if (s[c] == '1')
                A.push_back({r, c});
    }
    for (int r = 0; r < hb; r++) {
        cin >> s;
        for (int c = 0; c < wb; c++)
            if (s[c] == '1')
                B.push_back({r, c});
    }
    if (A.empty() || B.empty()) {
        cout << "-1 0\n";
        return 0;
    }
    int best = INT_MAX, ways = 0;
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (int dx = 1 - hb; dx < ha; dx++)
        for (int dy = 1 - wb; dy < wa; dy++) {
            int x0 = min(0, dx) - 1, y0 = min(0, dy) - 1, H = max(ha, dx + hb) - x0 + 1,
                W = max(wa, dy + wb) - y0 + 1;
            vector<int> a(H * W), b(H * W);
            for (auto [r, c] : A)
                a[(r - x0) * W + c - y0] = 1;
            for (auto [r, c] : B)
                b[(r + dx - x0) * W + c + dy - y0] = 1;
            auto comp = [&](int kind) {
                vector<char> vis(H * W);
                int ans = 0;
                for (int i = 0; i < H * W; i++) {
                    bool ok = kind == 0   ? (a[i] && b[i])
                              : kind == 1 ? (a[i] || b[i])
                                          : !(a[i] || b[i]);
                    if (!ok || vis[i])
                        continue;
                    ans++;
                    vector<int> st{i};
                    vis[i] = 1;
                    while (!st.empty()) {
                        int z = st.back();
                        st.pop_back();
                        int r = z / W, c = z % W;
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d], nc = c + dc[d];
                            if (nr < 0 || nr >= H || nc < 0 || nc >= W)
                                continue;
                            int j = nr * W + nc;
                            bool good = kind == 0   ? (a[j] && b[j])
                                        : kind == 1 ? (a[j] || b[j])
                                                    : !(a[j] || b[j]);
                            if (good && !vis[j]) {
                                vis[j] = 1;
                                st.push_back(j);
                            }
                        }
                    }
                }
                return ans;
            };
            if (comp(0) != 1 || comp(1) != 1 || comp(2) != 2)
                continue;
            int per = 0;
            for (int r = 1; r < H - 1; r++)
                for (int c = 1; c < W - 1; c++)
                    if (a[r * W + c] || b[r * W + c])
                        for (int d = 0; d < 4; d++) {
                            int j = (r + dr[d]) * W + c + dc[d];
                            per += !(a[j] || b[j]);
                        }
            if (per < best) {
                best = per;
                ways = 1;
            } else if (per == best)
                ways++;
        }
    cout << (ways ? best : -1) << ' ' << ways << '\n';
}

