        cin >> x;
    string op;
    if (n > 1)
        cin >> op;
    using P = pair<int, ll>;
    vector<vector<map<int, P>>> d(n, vector<map<int, P>>(n));
    for (int i = 0; i < n; i++)
        d[i][i][a[i]] = {0, 1};
    for (int len = 2; len <= n; len++)
        for (int l = 0; l + len <= n; l++) {
            int r = l + len - 1;
            for (int k = l; k < r; k++)
                for (auto [x, px] : d[l][k])
                    for (auto [y, py] : d[k + 1][r]) {
                        int z = op[k] == '+' ? x + y : x - y,
                            c = px.first + py.first + (abs(z) > B), v = clamp(z, -B, B);
                        ll w = px.second * py.second % MOD;
                        auto it = d[l][r].find(v);
                        if (it == d[l][r].end() || c < it->second.first)
                            d[l][r][v] = {c, w};
                        else if (c == it->second.first)
                            it->second.second = (it->second.second + w) % MOD;
                    }
        }
