#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q;
    cin >> n >> m >> q;
    vector<pair<int, int>> e(m);
    for (auto &[a, b] : e) {
        cin >> a >> b;
        --a;
        --b;
    }
    vector<array<int, 3>> qs(q);
    for (auto &x : qs) {
        cin >> x[0] >> x[1] >> x[2];
        --x[0];
        --x[1];
    }
    vector<int> lo(q), hi(q, m + 1);
    while (true) {
        vector<vector<int>> b(m + 1);
        bool any = false;
        for (int i = 0; i < q; i++)
            if (lo[i] < hi[i]) {
                b[(lo[i] + hi[i]) / 2].push_back(i);
                any = true;
            }
        if (!any)
            break;
        vector<int> p(n), sz(n, 1);
        iota(p.begin(), p.end(), 0);
        auto find = [&](int x) {
            while (x != p[x]) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        };
        for (int t = 0; t <= m; t++) {
            if (t) {
                auto [u, v] = e[t - 1];
                u = find(u);
                v = find(v);
                if (u != v) {
                    if (sz[u] < sz[v])
                        swap(u, v);
                    p[v] = u;
                    sz[u] += sz[v];
                }
            }
            for (int i : b[t]) {
                auto [u, v, k] = qs[i];
                int a = find(u), c = find(v);
                if (a == c && sz[a] >= k)
                    hi[i] = t;
                else
                    lo[i] = t + 1;
            }
        }
    }
    for (int x : lo)
        cout << (x <= m ? x : -1) << '\n';
}

