#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
struct S {
    ll n = 0, l = 0, r = 0, p = 0, s = 0, z = 0;
};
S mergeS(S a, S b) {
    if (!a.n)
        return b;
    if (!b.n)
        return a;
    bool e = a.r == b.l;
    return {a.n + b.n,
            a.l,
            b.r,
            a.p + (e && a.p == a.n ? b.p : 0),
            b.s + (e && b.s == b.n ? a.s : 0),
            a.z + b.z + (e ? 2 * a.s * b.p : 0)};
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q, N = 1;
    cin >> n >> q;
    while (N < n)
        N *= 2;
    vector<S> t(2 * N);
    for (int i = 0; i < n; i++) {
        ll x;
        cin >> x;
        t[N + i] = {1, x, x, 1, 1, 1};
    }
    for (int i = N - 1; i; i--)
        t[i] = mergeS(t[2 * i], t[2 * i + 1]);
    while (q--) {
        char op;
        int x;
        ll y;
        cin >> op >> x >> y;
        if (op == 'U') {
            int i = N + x - 1;
            t[i] = {1, y, y, 1, 1, 1};
            for (i /= 2; i; i /= 2)
                t[i] = mergeS(t[2 * i], t[2 * i + 1]);
        } else {
            int l = N + x - 1, r = N + y;
            S a, b;
            while (l < r) {
                if (l & 1)
                    a = mergeS(a, t[l++]);
                if (r & 1)
                    b = mergeS(t[--r], b);
                l /= 2;
                r /= 2;
            }
            cout << mergeS(a, b).z << '\n';
        }
    }
}

#include <bits/stdc++.h>
