using ll = long long;
const ll MOD = 1000000007;
using P = pair<ll, ll>;
const ll INF = 4e18;
P mg(P a, P b) {
    if (a.first != b.first)
        return min(a, b);
    return {a.first, (a.second + b.second) % MOD};
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, m;
    cin >> N >> m;
    vector<array<int, 3>> e(m);
    vector<int> x{0};
    for (auto &a : e) {
        cin >> a[0] >> a[1] >> a[2];
        x.push_back(a[1]);
    }
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    sort(e.begin(), e.end(), [](auto a, auto b) { return a[1] < b[1]; });
    int S = 1;
    while (S < (int)x.size())
        S *= 2;
    vector<P> t(2 * S, {INF, 0});
    auto up = [&](int i, P v) {
        i += S;
        t[i] = mg(t[i], v);
        while (i /= 2)
            t[i] = mg(t[2 * i], t[2 * i + 1]);
    };
    auto qu = [&](int l, int r) {
        P a = {INF, 0};
        for (l += S, r += S; l < r; l /= 2, r /= 2) {
            if (l & 1)
                a = mg(a, t[l++]);
            if (r & 1)
                a = mg(a, t[--r]);
        }
        return a;
    };
    up(0, {0, 1});
    for (auto [l, r, w] : e) {
        int j = lower_bound(x.begin(), x.end(), r) - x.begin(),
            i = lower_bound(x.begin(), x.end(), l - 1) - x.begin();
        auto [d, c] = qu(i, j);
        if (d < INF)
            up(j, {d + w, c});
    }
    int j = lower_bound(x.begin(), x.end(), N) - x.begin();
    auto [d, c] = j < (int)x.size() && x[j] == N ? qu(j, j + 1) : P{INF, 0};
    cout << (d == INF ? -1 : d) << ' ' << c << '\n';
}

