const ll MOD = 1000000007;
using S = array<ll, 6>;
S mg(S a, S b) {
    return {a[0] + b[0],
            a[1] + b[1],
            a[2] + b[2] + a[0] * b[1],
            a[3] + b[3] + a[1] * b[0],
            a[4] + b[4] + a[2] * b[0] + a[0] * b[3],
            a[5] + b[5] + a[3] * b[1] + a[1] * b[2]};
}
vector<S> tr;
vector<int> lazy;
string s;
void flip(int v) {
    swap(tr[v][0], tr[v][1]);
    swap(tr[v][2], tr[v][3]);
    swap(tr[v][4], tr[v][5]);
    lazy[v] ^= 1;
}
void build(int v, int l, int r) {
    if (r - l == 1) {
        tr[v][s[l] - '0'] = 1;
        return;
    }
    int m = (l + r) / 2;
    build(v * 2, l, m);
    build(v * 2 + 1, m, r);
    tr[v] = mg(tr[v * 2], tr[v * 2 + 1]);
}
S run(int v, int l, int r, int L, int R, bool ch) {
    if (R <= l || r <= L)
        return {};
    if (L <= l && r <= R) {
        if (ch)
            flip(v);
        return tr[v];
    }
    if (lazy[v]) {
        flip(v * 2);
        flip(v * 2 + 1);
        lazy[v] = 0;
    }
    int m = (l + r) / 2;
    S a = run(v * 2, l, m, L, R, ch), b = run(v * 2 + 1, m, r, L, R, ch);
    if (ch)
        tr[v] = mg(tr[v * 2], tr[v * 2 + 1]);
    return mg(a, b);
}
