    cin >> n >> q >> s;
    tr.resize(4 * n);
    lazy.resize(4 * n);
    build(1, 0, n);
    while (q--) {
        int t, l, r;
        cin >> t >> l >> r;
        auto a = run(1, 0, n, l - 1, r, t == 1);
        if (t == 2)
            cout << a[4] << '\n';
    }
}

