#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
ll pw(ll a, ll b) {
    ll z = 1;
    for (; b; b /= 2, a = a * a % MOD)
        if (b & 1)
            z = z * a % MOD;
    return z;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K, V;
    cin >> n >> K >> V;
    vector<int> f(V + 1);
    for (int i = 0, x; i < n; i++) {
        cin >> x;
        f[x]++;
    }
    vector<ll> fac(n + 1, 1), inv(n + 1, 1);
    for (int i = 1; i <= n; i++)
        fac[i] = fac[i - 1] * i % MOD;
    inv[n] = pw(fac[n], MOD - 2);
    for (int i = n; i; i--)
        inv[i - 1] = inv[i] * i % MOD;
    auto C = [&](int a, int b) {
        return b < 0 || b > a ? 0LL : fac[a] * inv[b] % MOD * inv[a - b] % MOD;
    };
    vector<int> mu(V + 1), pr, comp(V + 1);
    mu[1] = 1;
    for (int i = 2; i <= V; i++) {
        if (!comp[i]) {
            pr.push_back(i);
            mu[i] = -1;
        }
        for (int p : pr) {
            if ((ll)i * p > V)
                break;
            comp[i * p] = 1;
            if (i % p == 0)
                break;
            mu[i * p] = -mu[i];
        }
    }
    ll ans = 0;
    for (int d = 1; d <= V; d += 2)
        if (mu[d]) {
            int o = 0, e = 0;
            for (int j = d; j <= V; j += d)
                if (j & 1)
                    o += f[j];
                else
                    e += f[j];
            ll val = 0;
            for (int j = 1; j <= min(K, o); j += 2)
                val = (val + C(o, j) * C(e, K - j)) % MOD;
            ans = (ans + mu[d] * val) % MOD;
        }
    cout << (ans + MOD) % MOD << '\n';
}

