const ll MOD = 1000000007;
struct Bag {
    vector<ll> c, s;
    vector<ll> *x;
    ll cnt, total = 0;
    Bag(vector<ll> &v, ll n) : c(v.size() + 1), s(v.size() + 1), x(&v), cnt(n) {
        add(0, n);
    }
    void add(ll v, ll d) {
        total += v * d;
        for (int i = lower_bound(x->begin(), x->end(), v) - x->begin() + 1;
             i < (int)c.size(); i += i & -i) {
            c[i] += d;
            s[i] += v * d;
        }
    }
    ll get(ll v) {
        int i = upper_bound(x->begin(), x->end(), -v) - x->begin();
        ll C = 0, S = 0;
        for (; i; i -= i & -i) {
            C += c[i];
            S += s[i];
        }
        return total - S + v * (cnt - C);
    }
};
int main() {
