    vector<ll> r(n), c(m), x{0};
    while (q--) {
        char t;
        int i;
        ll v;
        cin >> t >> i >> v;
        --i;
        ops.push_back({t, i, v});
        auto &a = t == 'R' ? r : c;
        a[i] += v;
        x.push_back(a[i]);
    }
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    Bag R(x, n), C(x, m);
    fill(r.begin(), r.end(), 0);
    fill(c.begin(), c.end(), 0);
    ll ans = 0;
    for (auto [t, i, v] : ops) {
        auto &a = t == 'R' ? r : c;
        Bag &own = t == 'R' ? R : C, &other = t == 'R' ? C : R;
        ll old = a[i], nw = old + v;
        ans += other.get(nw) - other.get(old);
        own.add(old, -1);
        own.add(nw, 1);
        a[i] = nw;
        cout << ans << '\n';
    }
}

