            u = tr[u][k];
            cnt[u]++;
        }
    }
    for (int i = 0; i < n; i++) {
        int u = 0, ans = -1;
        for (int j = 0; j < (int)s[i].size(); j++) {
            u = tr[u][s[i][j] - 'a'];
            if (cnt[u] <= K[i]) {
                ans = j + 1;
                break;
            }
        }
        cout << ans << '\n';
    }
}

