#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
struct Data {
    vector<int> st, cnt;
    vector<bitset<2001>> mask;
};
Data scan(string s, string p, bool rev) {
    int m = p.size();
    vector<int> pi(m);
    for (int i = 1; i < m; i++) {
        int j = pi[i - 1];
        while (j && p[i] != p[j])
            j = pi[j - 1];
        if (p[i] == p[j])
            j++;
        pi[i] = j;
    }
    Data d;
    d.mask.resize(m + 1);
    for (int k = 1; k <= m; k++) {
        d.mask[k] = d.mask[pi[k - 1]];
        d.mask[k].set(rev ? m - k : k);
    }
    d.st.push_back(0);
    d.cnt.push_back(0);
    int z = 0;
    for (char c : s) {
        if (z == m)
            z = pi.back();
        while (z && p[z] != c)
            z = pi[z - 1];
        if (p[z] == c)
            z++;
        d.st.push_back(z);
        d.cnt.push_back(d.cnt.back() + (z == m));
    }
    return d;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q;
    string s, p;
    cin >> n >> m >> q >> s >> p;
    auto a = scan(s, p, false);
    reverse(s.begin(), s.end());
    reverse(p.begin(), p.end());
    auto b = scan(s, p, true);
    bitset<2001> valid;
    for (int k = 1; k < m; k++)
        valid.set(k);
    ll total = 0, weighted = 0;
    for (int i = 1, l, r; i <= q; i++) {
        cin >> l >> r;
        ll z = a.cnt[l - 1] + b.cnt[n - r] +
               (a.mask[a.st[l - 1]] & b.mask[b.st[n - r]] & valid).count();
        total += z;
        weighted += (ll)i * z;
    }
    cout << total << ' ' << weighted << '\n';
}

