#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
const int P = 998244353;
int power(int a, int b) {
    int z = 1;
    for (; b; b /= 2, a = (ll)a * a % P)
        if (b & 1)
            z = (ll)z * a % P;
    return z;
}
void ntt(vector<int> &a, bool inv) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int b = n >> 1;
        for (; j & b; b >>= 1)
            j ^= b;
        j ^= b;
        if (i < j)
            swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len *= 2) {
        int root = power(3, (P - 1) / len);
        if (inv)
            root = power(root, P - 2);
        for (int i = 0; i < n; i += len) {
            ll w = 1;
            for (int j = 0; j < len / 2; j++) {
                int u = a[i + j], v = w * a[i + j + len / 2] % P;
                a[i + j] = u + v < P ? u + v : u + v - P;
                a[i + j + len / 2] = u - v >= 0 ? u - v : u - v + P;
                w = w * root % P;
            }
        }
    }
    if (inv) {
        ll z = power(n, P - 2);
        for (int &x : a)
            x = x * z % P;
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, V = 0;
    cin >> n;
    vector<pair<int, int>> d(n);
    for (auto &[a, c] : d) {
        cin >> a >> c;
        V = max(V, a);
    }
    int N = 1;
    while (N < 2 * V + 1)
        N *= 2;
    vector<int> a(N), b(N);
    for (auto [x, c] : d)
        (c ? b : a)[x]++;
    ntt(a, false);
    ntt(b, false);
    for (int i = 0; i < N; i++)
        a[i] = (ll)a[i] * b[i] % P;
    ntt(a, true);
    vector<int> prime(2 * V + 1, 1);
    prime[0] = 0;
    if (V)
        prime[1] = 0;
    for (int p = 2; p * p <= 2 * V; p++)
        if (prime[p])
            for (int j = p * p; j <= 2 * V; j += p)
                prime[j] = 0;
    ll ans = 0;
    for (int s = 2; s <= 2 * V; s++)
        if (prime[s])
            ans += a[s];
    cout << ans << '\n';
}

