import sys, heapq

t = sys.stdin.buffer.read().split()
s = t[1].decode()
on = {(0, 0)}
heaps = [[(0, 0, 0)] for _ in range(4)]
x = y = 0
best = first = 0
count = 1
delta = {"N": (0, 1), "S": (0, -1), "E": (1, 0), "W": (-1, 0)}
for i, c in enumerate(s, 1):
    dx, dy = delta[c]
    x += dx
    y += dy
    p = (x, y)
    if p in on:
        on.remove(p)
    else:
        on.add(p)
        for h, v in zip(heaps, (x, -x, y, -y)):
            heapq.heappush(h, (v, x, y))
    if on:
        for h in heaps:
            while (h[0][1], h[0][2]) not in on:
                heapq.heappop(h)
        per = -2 * sum(h[0][0] for h in heaps)
    else:
        per = 0
    if per > best:
        best = per
        first = i
        count = 1
    elif per == best:
        count += 1
print(best, first, count)

