#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    set<pair<int, int>> on{{0, 0}};
    multiset<int> X{0}, Y{0};
    int x = 0, y = 0, best = 0, first = 0, cnt = 1;
    for (int i = 1; i <= n; i++) {
        char c = s[i - 1];
        x += (c == 'E') - (c == 'W');
        y += (c == 'N') - (c == 'S');
        pair<int, int> p{x, y};
        if (on.count(p)) {
            on.erase(p);
            X.erase(X.find(x));
            Y.erase(Y.find(y));
        } else {
            on.insert(p);
            X.insert(x);
            Y.insert(y);
        }
        int per =
            on.empty() ? 0 : 2 * (*X.rbegin() - *X.begin() + *Y.rbegin() - *Y.begin());
        if (per > best) {
            best = per;
            first = i;
            cnt = 1;
        } else if (per == best)
            cnt++;
    }
    cout << best << ' ' << first << ' ' << cnt << '\n';
}
